result=js(r'''(async()=>{
// Baseline renderer contracts; citywide.browser.py covers the rollout default.
const legacyCity=plots=>kit.createCityBuildings(plots,{rollout:false});
const T=await import('three'),shop=await import('./js/world/shop-slice.js'),kit=await import('./js/world/building-kit.js'),{stops}=await import('./js/content.js'),{routePoints,routeCurve}=await import('./js/world/layout.js'),{buildCity}=await import('./js/world/city.js');const check=(v,m)=>{if(!v)throw Error(m)},pts=routePoints(stops.length),plots=[];buildCity(()=>{},stops,pts,routeCurve(T,pts),undefined,undefined,p=>plots.push(p));
check(JSON.stringify(shop.SHOP_INTEGRATION_IDS)===JSON.stringify(['block--295--34','block--282--34','block--269--34','infill-1--36','frontage-stop-hero--255-1--9','frontage-stop-hero--255-1-0']),'exact six existing lots');const selected=shop.SHOP_INTEGRATION_IDS.map(id=>plots.find(p=>p.id===id));check(selected.every(Boolean),'all lots exist');const g=shop.createShopIntegration(selected,plots);check(g.children.length===3&&g.children.every(c=>c.children.length===3),'three local batches');const materials=new Set,maps=new Set;let triangles=0,renderables=0;
g.traverse(m=>{if(!m.isMesh)return;renderables++;materials.add(m.material);Object.values(m.material).forEach(v=>{if(v?.isTexture)maps.add(v)});const a=m.geometry.attributes;triangles+=a.position.count/3;check(m.geometry.boundingBox&&m.geometry.boundingSphere&&m.frustumCulled&&m.castShadow===m.name.endsWith('mass'),'culling/shadow');for(const key of ['position','normal','uv','aSurface','color'])check(a[key]?.count===a.position.count,'merge attribute');});check(renderables===9&&triangles<12000&&materials.size===2&&maps.size===4,'local budget/shared resources');
for(const p of selected){const h=shop.createShopSlice(p,plots);for(const m of h.children){const a=m.geometry.attributes.position;for(let i=0;i<a.count;i++)check(Math.abs(a.getX(i))<=p.width/2+.001&&Math.abs(a.getZ(i))<=p.depth/2+.001&&a.getY(i)>=0&&a.getY(i)<=p.height,'source footprint/height');}h.children.forEach(m=>m.geometry.dispose());}
const fp=o=>{const a=[];o.traverse(m=>{if(m.isMesh)a.push({name:m.name,cast:m.castShadow,attributes:Object.fromEntries(Object.entries(m.geometry.attributes).map(([k,v])=>[k,Array.from(v.array)])),instances:m.instanceMatrix?Array.from(m.instanceMatrix.array):null,colors:m.instanceColor?Array.from(m.instanceColor.array):null})});return JSON.stringify(a)};
const city=legacyCity(plots),actual=city.getObjectByName('hero-final-frontages');check(actual&&fp(actual)===fp(g),'integration');const others=new T.Group();city.children.filter(o=>o!==actual).forEach(o=>others.add(o.clone()));check(fp(others)===fp(legacyCity(plots.filter(p=>!shop.SHOP_INTEGRATION_IDS.includes(p.id)))),'approved architecture/paving unchanged');check(fp(g)===fp(shop.createShopIntegration(selected,plots)),'determinism');let disposed=0;actual.traverse(m=>{if(m.isMesh)m.geometry.addEventListener('dispose',()=>disposed++)});city.userData.dispose();city.userData.dispose();check(disposed===9,'disposal once');let rejected=false;try{shop.createShopIntegration([{...selected[0],height:20}],plots)}catch(e){rejected=e instanceof TypeError}check(rejected,'descriptor guard');return {pass:true,ids:shop.SHOP_INTEGRATION_IDS,renderables,triangles,materials:materials.size,maps:maps.size,chunks:g.children.length};})()''')
print(result)
assert isinstance(result,dict) and result.get('pass'),result
